R["javi-checkpoint-m2-design"] = "\nimport java.util.*;\n\npublic class Solution {\n    public sealed interface Discount permits None, Percent, Flat {}\n    public record None() implements Discount {}\n    public record Percent(int pct) implements Discount {\n        public Percent {\n            if (pct < 0 || pct > 100) throw new IllegalArgumentException(\"pct 0..100\");\n        }\n    }\n    public record Flat(int cents) implements Discount {}\n\n    public static int apply(Discount d, int priceCents) {\n        return switch (d) {\n            case None n -> priceCents;\n            case Percent p -> priceCents - priceCents * p.pct() / 100;\n            case Flat f -> Math.max(0, priceCents - f.cents());\n        };\n    }\n\n    public static Discount best(List<Discount> options, int priceCents) {\n        Discount winner = null;\n        int bestPrice = Integer.MAX_VALUE;\n        for (Discount d : options) {\n            int p = apply(d, priceCents);\n            if (p < bestPrice) { bestPrice = p; winner = d; }\n        }\n        return winner;\n    }\n}\n";
W["javi-checkpoint-m2-design"] = "\nimport java.util.*;\n\npublic class Solution {\n    public sealed interface Discount permits None, Percent, Flat {}\n    public record None() implements Discount {}\n    public record Percent(int pct) implements Discount {\n        public Percent {\n            if (pct < 0 || pct > 100) throw new IllegalArgumentException(\"pct 0..100\");\n        }\n    }\n    public record Flat(int cents) implements Discount {}\n\n    public static int apply(Discount d, int priceCents) {\n        return switch (d) {\n            case None n -> priceCents;\n            case Percent p -> priceCents - priceCents * p.pct() / 100;\n            // W: Flat does not floor at zero \u2014 returns negative prices,\n            // which is the behavioral near-miss the tests expose.\n            case Flat f -> priceCents - f.cents();\n        };\n    }\n\n    public static Discount best(List<Discount> options, int priceCents) {\n        Discount winner = null;\n        int bestPrice = Integer.MAX_VALUE;\n        for (Discount d : options) {\n            int p = apply(d, priceCents);\n            if (p < bestPrice) { bestPrice = p; winner = d; }\n        }\n        return winner;\n    }\n}\n";
R["javi-p3-pecs-stats"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static double sum(List<? extends Number> src) {\n        double t = 0;\n        for (Number n : src) t += n.doubleValue();\n        return t;\n    }\n    public static void fill(List<? super Integer> dst, int a, int b, int c) {\n        dst.add(a); dst.add(b); dst.add(c);\n    }\n    public static List<Number> demo() {\n        List<Number> out = new ArrayList<>();\n        fill(out, 7, 8, 9);\n        return out;\n    }\n}\n";
W["javi-p3-pecs-stats"] = "\nimport java.util.*;\n\npublic class Solution {\n    // W: sum uses intValue() \u2014 truncates every non-integer silently.\n    // 2.5 contributes 2, so mixed sums drift below the true total.\n    public static double sum(List<? extends Number> src) {\n        double t = 0;\n        for (Number n : src) t += n.intValue();\n        return t;\n    }\n    public static void fill(List<? super Integer> dst, int a, int b, int c) {\n        dst.add(a); dst.add(b); dst.add(c);\n    }\n    public static List<Number> demo() {\n        List<Number> out = new ArrayList<>();\n        fill(out, 7, 8, 9);\n        return out;\n    }\n}\n";
R["javi-p3-generic-max"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static <T extends Comparable<T>> T max(List<T> xs) {\n        if (xs == null || xs.isEmpty()) throw new IllegalArgumentException(\"xs required\");\n        T best = xs.get(0);\n        for (T x : xs) if (x.compareTo(best) > 0) best = x;\n        return best;\n    }\n    public static Integer maxInt(List<Integer> xs) { return max(xs); }\n    public static String maxString(List<String> xs) { return max(xs); }\n}\n";
W["javi-p3-generic-max"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static <T extends Comparable<T>> T max(List<T> xs) {\n        if (xs == null || xs.isEmpty()) throw new IllegalArgumentException(\"xs required\");\n        T best = xs.get(0);\n        // W: comparison flipped \u2014 converges to the MINIMUM, the classic\n        // sign-slip in comparison loops.\n        for (T x : xs) if (x.compareTo(best) < 0) best = x;\n        return best;\n    }\n    public static Integer maxInt(List<Integer> xs) { return max(xs); }\n    public static String maxString(List<String> xs) { return max(xs); }\n}\n";
R["javi-p3-erasure-token"] = "\nimport java.util.*;\nimport java.util.function.Function;\n\npublic class Solution {\n    public static <T> List<T> fill(int n, Class<T> type, Function<Object, T> maker) {\n        List<T> out = new ArrayList<>();\n        for (int i = 0; i < n; i++) out.add(maker.apply(i));\n        return out;\n    }\n    public static <T> List<T> nCopiesOf(int n, T value) {\n        List<T> out = new ArrayList<>();\n        for (int i = 0; i < n; i++) out.add(value);\n        return out;\n    }\n}\n";
W["javi-p3-erasure-token"] = "\nimport java.util.*;\nimport java.util.function.Function;\n\npublic class Solution {\n    public static <T> List<T> fill(int n, Class<T> type, Function<Object, T> maker) {\n        List<T> out = new ArrayList<>();\n        for (int i = 0; i < n; i++) out.add(maker.apply(i));\n        return out;\n    }\n    // W: fills n+1 copies \u2014 off-by-one the size-sensitive test catches.\n    public static <T> List<T> nCopiesOf(int n, T value) {\n        List<T> out = new ArrayList<>();\n        for (int i = 0; i <= n; i++) out.add(value);\n        return out;\n    }\n}\n";
R["javi-checkpoint-m3-generics"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static <T extends Comparable<T>> List<T> topN(List<T> xs, int n) {\n        if (xs == null || xs.isEmpty()) throw new IllegalArgumentException(\"xs required\");\n        if (n <= 0) throw new IllegalArgumentException(\"n must be positive\");\n        List<T> sorted = new ArrayList<>(xs);\n        sorted.sort(Comparator.reverseOrder());\n        return new ArrayList<>(sorted.subList(0, Math.min(n, sorted.size())));\n    }\n\n    public static double sumNumbers(List<? extends Number> xs) {\n        double t = 0;\n        for (Number n : xs) t += n.doubleValue();\n        return t;\n    }\n\n    public static <T> List<? super T> drain(List<T> src, List<? super T> dst) {\n        dst.addAll(src);\n        src.clear();\n        return dst;\n    }\n}\n";
W["javi-checkpoint-m3-generics"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static <T extends Comparable<T>> List<T> topN(List<T> xs, int n) {\n        if (xs == null || xs.isEmpty()) throw new IllegalArgumentException(\"xs required\");\n        if (n <= 0) throw new IllegalArgumentException(\"n must be positive\");\n        List<T> sorted = new ArrayList<>(xs);\n        // W: ASCENDING order \u2014 returns the SMALLEST n. Any descending\n        // expectation (and duplicate-max handling) exposes the bug.\n        sorted.sort(Comparator.naturalOrder());\n        return new ArrayList<>(sorted.subList(0, Math.min(n, sorted.size())));\n    }\n\n    public static double sumNumbers(List<? extends Number> xs) {\n        double t = 0;\n        for (Number n : xs) t += n.doubleValue();\n        return t;\n    }\n\n    public static <T> List<? super T> drain(List<T> src, List<? super T> dst) {\n        dst.addAll(src);\n        src.clear();\n        return dst;\n    }\n}\n";
R["javi-p4-sort-employees"] = "\nimport java.util.*;\n\npublic class Solution {\n    public record Employee(String name, String dept, int salary) {}\n\n    public static List<String> topPaidByDept(List<Employee> staff, int n) {\n        Map<String, List<Employee>> byDept = new TreeMap<>();\n        for (Employee e : staff) {\n            byDept.computeIfAbsent(e.dept(), k -> new ArrayList<>()).add(e);\n        }\n        List<String> out = new ArrayList<>();\n        Comparator<Employee> rank =\n            Comparator.comparingInt(Employee::salary).reversed()\n                      .thenComparing(Employee::name);\n        for (var entry : byDept.entrySet()) {\n            List<Employee> group = entry.getValue();\n            group.sort(rank);\n            for (int i = 0; i < Math.min(n, group.size()); i++) {\n                out.add(entry.getKey() + \":\" + group.get(i).name());\n            }\n        }\n        return out;\n    }\n}\n";
W["javi-p4-sort-employees"] = "\nimport java.util.*;\n\npublic class Solution {\n    public record Employee(String name, String dept, int salary) {}\n\n    public static List<String> topPaidByDept(List<Employee> staff, int n) {\n        Map<String, List<Employee>> byDept = new TreeMap<>();\n        for (Employee e : staff) {\n            byDept.computeIfAbsent(e.dept(), k -> new ArrayList<>()).add(e);\n        }\n        List<String> out = new ArrayList<>();\n        // W: forgot .reversed() \u2014 picks the LOWEST paid, then ties break\n        // by name DESCENDING. Every salary expectation exposes it.\n        Comparator<Employee> rank =\n            Comparator.comparingInt(Employee::salary)\n                      .thenComparing(Employee::name, Comparator.reverseOrder());\n        for (var entry : byDept.entrySet()) {\n            List<Employee> group = entry.getValue();\n            group.sort(rank);\n            for (int i = 0; i < Math.min(n, group.size()); i++) {\n                out.add(entry.getKey() + \":\" + group.get(i).name());\n            }\n        }\n        return out;\n    }\n}\n";
R["javi-p4-task-queue"] = "\nimport java.util.*;\n\npublic class Solution {\n    public record Task(String name, int priority) {}\n\n    public static List<String> processTasks(List<Task> tasks, int slots) {\n        PriorityQueue<Object[]> pq = new PriorityQueue<>(\n            (x, y) -> {\n                int c = Integer.compare(((Task) x[0]).priority(), ((Task) y[0]).priority());\n                return c != 0 ? c : Integer.compare((int) x[1], (int) y[1]);\n            });\n        int idx = 0;\n        for (Task t : tasks) pq.add(new Object[]{t, idx++});\n        List<String> out = new ArrayList<>();\n        while (!pq.isEmpty() && out.size() < slots) out.add(((Task) pq.poll()[0]).name());\n        return out;\n    }\n}\n";
W["javi-p4-task-queue"] = "\nimport java.util.*;\n\npublic class Solution {\n    public record Task(String name, int priority) {}\n\n    public static List<String> processTasks(List<Task> tasks, int slots) {\n        // W: priority DESCENDING \u2014 processes 5 before 1. The \"most\n        // urgent first\" expectation fails immediately.\n        PriorityQueue<Object[]> pq = new PriorityQueue<>(\n            (x, y) -> {\n                int c = Integer.compare(((Task) y[0]).priority(), ((Task) x[0]).priority());\n                return c != 0 ? c : Integer.compare((int) x[1], (int) y[1]);\n            });\n        int idx = 0;\n        for (Task t : tasks) pq.add(new Object[]{t, idx++});\n        List<String> out = new ArrayList<>();\n        while (!pq.isEmpty() && out.size() < slots) out.add(((Task) pq.poll()[0]).name());\n        return out;\n    }\n}\n";
R["javi-p4-seal-registry"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static class Registry {\n        private final Map<String, Integer> map = new HashMap<>();\n        public void put(String k, int v) { map.put(k, v); }\n        public int get(String k) {\n            Integer v = map.get(k);\n            if (v == null) throw new NoSuchElementException(k);\n            return v;\n        }\n        public Map<String, Integer> snapshot() { return Collections.unmodifiableMap(map); }\n        public Map<String, Integer> frozenCopy() { return Map.copyOf(map); }\n    }\n\n    public static int totalOf(Map<String, Integer> values) {\n        int t = 0;\n        for (int v : values.values()) t += v;\n        return t;\n    }\n}\n";
W["javi-p4-seal-registry"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static class Registry {\n        private final Map<String, Integer> map = new HashMap<>();\n        public void put(String k, int v) { map.put(k, v); }\n        public int get(String k) {\n            Integer v = map.get(k);\n            if (v == null) throw new NoSuchElementException(k);\n            return v;\n        }\n        // W: \"copy\" delegates to the live map \u2014 a later put() leaks into\n        // the frozen copy, exactly the independence the test checks.\n        public Map<String, Integer> frozenCopy() { return map; }\n        public Map<String, Integer> snapshot() { return Collections.unmodifiableMap(map); }\n    }\n\n    public static int totalOf(Map<String, Integer> values) {\n        int t = 0;\n        for (int v : values.values()) t += v;\n        return t;\n    }\n}\n";
R["javi-checkpoint-m4-collections"] = "\nimport java.util.*;\n\npublic class Solution {\n    public record Player(String name, int score) implements Comparable<Player> {\n        @Override public int compareTo(Player o) {\n            int c = Integer.compare(o.score(), this.score());\n            return c != 0 ? c : this.name().compareTo(o.name());\n        }\n    }\n\n    public static List<String> top(List<Player> players, int n) {\n        List<Player> sorted = new ArrayList<>(players);\n        Collections.sort(sorted);\n        List<String> out = new ArrayList<>();\n        for (int i = 0; i < Math.min(n, sorted.size()); i++) out.add(sorted.get(i).name());\n        return out;\n    }\n\n    public static NavigableSet<Player> ranked(Set<Player> players) {\n        return new TreeSet<>(players);\n    }\n}\n";
W["javi-checkpoint-m4-collections"] = "\nimport java.util.*;\n\npublic class Solution {\n    public record Player(String name, int score) implements Comparable<Player> {\n        @Override public int compareTo(Player o) {\n            // W: ascending score \u2014 the leaderboard ranks the WORST first.\n            int c = Integer.compare(this.score(), o.score());\n            return c != 0 ? c : this.name().compareTo(o.name());\n        }\n    }\n\n    public static List<String> top(List<Player> players, int n) {\n        List<Player> sorted = new ArrayList<>(players);\n        Collections.sort(sorted);\n        List<String> out = new ArrayList<>();\n        for (int i = 0; i < Math.min(n, sorted.size()); i++) out.add(sorted.get(i).name());\n        return out;\n    }\n\n    public static NavigableSet<Player> ranked(Set<Player> players) {\n        return new TreeSet<>(players);\n    }\n}\n";
R["javi-p5-word-freq"] = "\nimport java.util.*;\nimport java.util.stream.*;\nimport java.util.function.Function;\n\npublic class Solution {\n    public static Map<String, Long> frequencies(List<String> words) {\n        return words.stream().collect(Collectors.groupingBy(Function.identity(), Collectors.counting()));\n    }\n    public static Map<Integer, List<String>> byLength(List<String> words) {\n        return words.stream().collect(Collectors.groupingBy(String::length));\n    }\n    public static Map<Boolean, List<String>> longWords(List<String> words) {\n        return words.stream().collect(Collectors.partitioningBy(w -> w.length() > 4));\n    }\n}\n";
W["javi-p5-word-freq"] = "\nimport java.util.*;\nimport java.util.stream.*;\nimport java.util.function.Function;\n\npublic class Solution {\n    // W: groupingBy but counts each group's DISTINCT words instead of\n    // occurrences \u2014 {\"a\":1} where {\"a\":2} is correct.\n    public static Map<String, Long> frequencies(List<String> words) {\n        return words.stream().collect(Collectors.groupingBy(Function.identity(),\n            Collectors.collectingAndThen(Collectors.toSet(), s -> (long) s.size())));\n    }\n    public static Map<Integer, List<String>> byLength(List<String> words) {\n        return words.stream().collect(Collectors.groupingBy(String::length));\n    }\n    public static Map<Boolean, List<String>> longWords(List<String> words) {\n        return words.stream().collect(Collectors.partitioningBy(w -> w.length() > 4));\n    }\n}\n";
R["javi-p5-sales-merge"] = "\nimport java.util.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public record Sale(String region, int amount) {}\n\n    public static Map<String, Integer> totalsByRegion(List<Sale> sales) {\n        return sales.stream().collect(Collectors.toMap(Sale::region, Sale::amount, Integer::sum));\n    }\n\n    public static Map.Entry<String, Integer> topRegion(List<Sale> sales) {\n        Map<String, Integer> totals = totalsByRegion(sales);\n        return totals.entrySet().stream()\n            .max(Map.Entry.<String, Integer>comparingByValue()\n                .thenComparing(Map.Entry.comparingByKey(Comparator.reverseOrder())))\n            .orElseThrow();\n    }\n}\n";
W["javi-p5-sales-merge"] = "\nimport java.util.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public record Sale(String region, int amount) {}\n\n    // W: toMap WITHOUT a merge function \u2014 a second sale in the same\n    // region throws IllegalStateException. The merge function exists\n    // precisely for this.\n    public static Map<String, Integer> totalsByRegion(List<Sale> sales) {\n        return sales.stream().collect(Collectors.toMap(Sale::region, Sale::amount));\n    }\n\n    public static Map.Entry<String, Integer> topRegion(List<Sale> sales) {\n        Map<String, Integer> totals = totalsByRegion(sales);\n        return totals.entrySet().stream()\n            .max(Map.Entry.<String, Integer>comparingByValue()\n                .thenComparing(Map.Entry.comparingByKey(Comparator.reverseOrder())))\n            .orElseThrow();\n    }\n}\n";
R["javi-p5-teeing-stats"] = "\nimport java.util.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public static double average(List<Integer> xs) {\n        if (xs == null || xs.isEmpty()) throw new IllegalArgumentException(\"xs required\");\n        return xs.stream().mapToInt(Integer::intValue).average().orElseThrow();\n    }\n\n    public static Map<String, Integer> rangeStats(List<Integer> xs) {\n        return xs.stream().collect(Collectors.teeing(\n            Collectors.minBy(Integer::compare),\n            Collectors.maxBy(Integer::compare),\n            (mn, mx) -> Map.of(\"min\", mn.orElseThrow(), \"max\", mx.orElseThrow())));\n    }\n\n    public static String classify(List<Integer> xs) {\n        return xs.stream().map(x -> x * 2)\n            .filter(v -> v > 10)\n            .map(String::valueOf)\n            .collect(Collectors.joining(\",\"));\n    }\n}\n";
W["javi-p5-teeing-stats"] = "\nimport java.util.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public static double average(List<Integer> xs) {\n        if (xs == null || xs.isEmpty()) throw new IllegalArgumentException(\"xs required\");\n        return xs.stream().mapToInt(Integer::intValue).average().orElseThrow();\n    }\n\n    public static Map<String, Integer> rangeStats(List<Integer> xs) {\n        return xs.stream().collect(Collectors.teeing(\n            Collectors.minBy(Integer::compare),\n            Collectors.maxBy(Integer::compare),\n            (mn, mx) -> Map.of(\"min\", mn.orElseThrow(), \"max\", mx.orElseThrow())));\n    }\n\n    // W: filter BEFORE doubling \u2014 keeps x > 10 rather than x*2 > 10,\n    // dropping values like 6 whose double qualifies.\n    public static String classify(List<Integer> xs) {\n        return xs.stream().filter(x -> x > 10)\n            .map(x -> x * 2)\n            .map(String::valueOf)\n            .collect(Collectors.joining(\",\"));\n    }\n}\n";
R["javi-checkpoint-m5-functional"] = "\nimport java.util.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public record Event(String user, String type, int ms) {}\n\n    public static Map<String, Long> eventsByType(List<Event> events) {\n        return events.stream().collect(Collectors.groupingBy(Event::type, Collectors.counting()));\n    }\n\n    public static Map<String, Integer> msByUser(List<Event> events) {\n        return events.stream().collect(Collectors.toMap(Event::user, Event::ms, Integer::sum));\n    }\n\n    public static Map<Boolean, List<String>> slowVsFast(List<Event> events, int threshold) {\n        Map<String, Double> avgByType = events.stream().collect(Collectors.groupingBy(\n            Event::type, Collectors.averagingInt(Event::ms)));\n        Map<Boolean, List<String>> out = new HashMap<>();\n        out.put(true, new ArrayList<>());\n        out.put(false, new ArrayList<>());\n        avgByType.forEach((type, avg) ->\n            out.get(avg > threshold).add(type));\n        out.get(true).sort(null);\n        out.get(false).sort(null);\n        return out;\n    }\n}\n";
W["javi-checkpoint-m5-functional"] = "\nimport java.util.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public record Event(String user, String type, int ms) {}\n\n    public static Map<String, Long> eventsByType(List<Event> events) {\n        return events.stream().collect(Collectors.groupingBy(Event::type, Collectors.counting()));\n    }\n\n    public static Map<String, Integer> msByUser(List<Event> events) {\n        return events.stream().collect(Collectors.toMap(Event::user, Event::ms, Integer::sum));\n    }\n\n    public static Map<Boolean, List<String>> slowVsFast(List<Event> events, int threshold) {\n        // W: compares each event's ms to the threshold instead of the\n        // TYPE average \u2014 one fast event in a slow type flips its bucket.\n        Map<Boolean, List<String>> out = new HashMap<>();\n        out.put(true, new ArrayList<>());\n        out.put(false, new ArrayList<>());\n        for (Event e : events) {\n            out.get(e.ms() > threshold).add(e.type());\n        }\n        out.get(true).sort(null);\n        out.get(false).sort(null);\n        return out;\n    }\n}\n";
R["javi-p6-resource-order"] = "\npublic class Solution {\n    public static class Res implements AutoCloseable {\n        private final String name;\n        private final StringBuilder log;\n        public Res(String name, StringBuilder log) { this.name = name; this.log = log; }\n        @Override public void close() { log.append(name).append(\":closed\"); }\n    }\n\n    public static String run(boolean failSecond, StringBuilder log) {\n        Res a = new Res(\"a\", log);\n        Res b = new Res(\"b\", log);\n        try (Res x = a; Res y = b) {\n            log.append(\"work\");\n            if (failSecond) throw new IllegalStateException(\"body failed\");\n        }\n        // return AFTER the try \u2014 close() appends during implicit finally,\n        // so returning inside would snapshot an incomplete log.\n        return log.toString();\n    }\n}\n";
W["javi-p6-resource-order"] = "\npublic class Solution {\n    public static class Res implements AutoCloseable {\n        private final String name;\n        private final StringBuilder log;\n        public Res(String name, StringBuilder log) { this.name = name; this.log = log; }\n        @Override public void close() { log.append(name).append(\":closed\"); }\n    }\n\n    // W: manual finally that returns INSIDE the try \u2014 the return value\n    // snapshots the log BEFORE finally appends the close markers, the\n    // exact trap the Beginner course taught. Both closes do run, but the\n    // caller never sees them.\n    public static String run(boolean failSecond, StringBuilder log) {\n        StringBuilder inner = new StringBuilder();\n        Res a = new Res(\"a\", inner);\n        Res b = new Res(\"b\", inner);\n        try {\n            log.append(\"work\");\n            if (failSecond) throw new IllegalStateException(\"body failed\");\n            return inner.toString();\n        } finally {\n            try { b.close(); } catch (RuntimeException ignored) { }\n            try { a.close(); } catch (RuntimeException ignored) { }\n        }\n    }\n}\n";
R["javi-p6-translation"] = "\npublic class Solution {\n    public static class StorageException extends RuntimeException {\n        public StorageException(String message, Throwable cause) { super(message, cause); }\n    }\n\n    public static class FlakyStore {\n        public static String fetch(String key) {\n            if (key.startsWith(\"!\")) throw new IllegalStateException(\"boom\");\n            return \"data-\" + key;\n        }\n    }\n\n    public static String repositoryGet(String key) {\n        try {\n            return FlakyStore.fetch(key);\n        } catch (IllegalStateException e) {\n            throw new StorageException(\"lookup failed for \" + key, e);\n        }\n    }\n}\n";
W["javi-p6-translation"] = "\npublic class Solution {\n    public static class StorageException extends RuntimeException {\n        public StorageException(String message, Throwable cause) { super(message, cause); }\n    }\n\n    public static class FlakyStore {\n        public static String fetch(String key) {\n            if (key.startsWith(\"!\")) throw new IllegalStateException(\"boom\");\n            return \"data-\" + key;\n        }\n    }\n\n    // W: swallows the failure and returns a placeholder \u2014 the caller\n    // cannot distinguish missing data from a real result.\n    public static String repositoryGet(String key) {\n        try {\n            return FlakyStore.fetch(key);\n        } catch (IllegalStateException e) {\n            return \"data-missing\";\n        }\n    }\n}\n";
R["javi-p6-account-errors"] = "\npublic class Solution {\n    public static class PaymentException extends RuntimeException {\n        public PaymentException(String message) { super(message); }\n    }\n\n    public static final class InsufficientFundsException extends PaymentException {\n        private final int shortfallCents;\n        public InsufficientFundsException(String message, int shortfallCents) {\n            super(message);\n            this.shortfallCents = shortfallCents;\n        }\n        public int shortfallCents() { return shortfallCents; }\n    }\n\n    public static void withdraw(int balance, int amount) {\n        if (amount < 0) throw new IllegalArgumentException(\"negative amount\");\n        if (amount > balance) throw new InsufficientFundsException(\"insufficient\", amount - balance);\n    }\n\n    public static int shortfallOf(RuntimeException e) {\n        return e instanceof InsufficientFundsException f ? f.shortfallCents() : -1;\n    }\n}\n";
W["javi-p6-account-errors"] = "\npublic class Solution {\n    public static class PaymentException extends RuntimeException {\n        public PaymentException(String message) { super(message); }\n    }\n\n    public static final class InsufficientFundsException extends PaymentException {\n        private final int shortfallCents;\n        public InsufficientFundsException(String message, int shortfallCents) {\n            super(message);\n            this.shortfallCents = shortfallCents;\n        }\n        public int shortfallCents() { return shortfallCents; }\n    }\n\n    // W: validates with the wrong exception type \u2014 negative amounts are\n    // a caller bug (IllegalArgumentException), not a domain failure.\n    public static void withdraw(int balance, int amount) {\n        if (amount < 0) throw new InsufficientFundsException(\"negative\", 0);\n        if (amount > balance) throw new InsufficientFundsException(\"insufficient\", amount - balance);\n    }\n\n    public static int shortfallOf(RuntimeException e) {\n        return e instanceof InsufficientFundsException f ? f.shortfallCents() : -1;\n    }\n}\n";
R["javi-checkpoint-m6-exceptions"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static class ValidationException extends RuntimeException {\n        private final List<String> errors;\n        public ValidationException(List<String> errors) {\n            super(String.join(\"; \", errors));\n            this.errors = List.copyOf(errors);\n        }\n        public List<String> errors() { return errors; }\n    }\n\n    public static void validate(List<String> fields) {\n        List<String> errors = new ArrayList<>();\n        for (int i = 0; i < fields.size(); i++) {\n            String f = fields.get(i);\n            if (f == null || f.isBlank()) errors.add(\"field \" + i + \" blank\");\n        }\n        if (!errors.isEmpty()) throw new ValidationException(errors);\n    }\n\n    public static int firstError(RuntimeException e) {\n        return e instanceof ValidationException ? 0 : -1;\n    }\n}\n";
W["javi-checkpoint-m6-exceptions"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static class ValidationException extends RuntimeException {\n        private final List<String> errors;\n        public ValidationException(List<String> errors) {\n            super(String.join(\"; \", errors));\n            this.errors = List.copyOf(errors);\n        }\n        public List<String> errors() { return errors; }\n    }\n\n    // W: fail-fast \u2014 throws at the FIRST blank field, so the errors list\n    // never carries more than one entry. A validation pipeline must\n    // collect everything.\n    public static void validate(List<String> fields) {\n        for (int i = 0; i < fields.size(); i++) {\n            String f = fields.get(i);\n            if (f == null || f.isBlank()) throw new ValidationException(List.of(\"field \" + i + \" blank\"));\n        }\n    }\n\n    public static int firstError(RuntimeException e) {\n        return e instanceof ValidationException ? 0 : -1;\n    }\n}\n";
R["javi-p7-csv-scanner"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static List<String> parseRow(String line) {\n        List<String> out = new ArrayList<>();\n        StringBuilder cur = new StringBuilder();\n        boolean inQuotes = false;\n        for (int i = 0; i < line.length(); i++) {\n            char c = line.charAt(i);\n            if (inQuotes) {\n                if (c == '\"') {\n                    if (i + 1 < line.length() && line.charAt(i + 1) == '\"') { cur.append('\"'); i++; }\n                    else inQuotes = false;\n                } else cur.append(c);\n            } else if (c == '\"') inQuotes = true;\n            else if (c == ',') { out.add(cur.toString()); cur.setLength(0); }\n            else cur.append(c);\n        }\n        out.add(cur.toString());\n        return out;\n    }\n}\n";
W["javi-p7-csv-scanner"] = "\nimport java.util.*;\n\npublic class Solution {\n    // W: naive split \u2014 quoted commas break fields and \"\" is copied\n    // literally. Exactly the bug the lesson warns about.\n    public static List<String> parseRow(String line) {\n        return new ArrayList<>(Arrays.asList(line.split(\",\", -1)));\n    }\n}\n";
R["javi-p7-csv-roundtrip"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static String writeRow(List<String> fields) {\n        StringBuilder out = new StringBuilder();\n        for (int i = 0; i < fields.size(); i++) {\n            if (i > 0) out.append(',');\n            String f = fields.get(i);\n            boolean needsQuote = f.indexOf(',') >= 0 || f.indexOf('\"') >= 0;\n            if (needsQuote) {\n                out.append('\"');\n                out.append(f.replace(\"\\\"\", \"\\\"\\\"\"));\n                out.append('\"');\n            } else out.append(f);\n        }\n        return out.toString();\n    }\n\n    public static List<String> roundTrip(List<String> fields) {\n        return parseRow(writeRow(fields));\n    }\n\n    static List<String> parseRow(String line) {\n        List<String> out = new ArrayList<>();\n        StringBuilder cur = new StringBuilder();\n        boolean inQuotes = false;\n        for (int i = 0; i < line.length(); i++) {\n            char c = line.charAt(i);\n            if (inQuotes) {\n                if (c == '\"') {\n                    if (i + 1 < line.length() && line.charAt(i + 1) == '\"') { cur.append('\"'); i++; }\n                    else inQuotes = false;\n                } else cur.append(c);\n            } else if (c == '\"') inQuotes = true;\n            else if (c == ',') { out.add(cur.toString()); cur.setLength(0); }\n            else cur.append(c);\n        }\n        out.add(cur.toString());\n        return out;\n    }\n}\n";
W["javi-p7-csv-roundtrip"] = "\nimport java.util.*;\n\npublic class Solution {\n    // W: quotes only on comma, ignores embedded quotes \u2014 a field like\n    // say \"hi\" round-trips WRONG (the quote escapes nothing).\n    public static String writeRow(List<String> fields) {\n        StringBuilder out = new StringBuilder();\n        for (int i = 0; i < fields.size(); i++) {\n            if (i > 0) out.append(',');\n            String f = fields.get(i);\n            if (f.indexOf(',') >= 0) out.append('\"').append(f).append('\"');\n            else out.append(f);\n        }\n        return out.toString();\n    }\n\n    public static List<String> roundTrip(List<String> fields) {\n        return parseRow(writeRow(fields));\n    }\n\n    static List<String> parseRow(String line) {\n        List<String> out = new ArrayList<>();\n        StringBuilder cur = new StringBuilder();\n        boolean inQuotes = false;\n        for (int i = 0; i < line.length(); i++) {\n            char c = line.charAt(i);\n            if (inQuotes) {\n                if (c == '\"') {\n                    if (i + 1 < line.length() && line.charAt(i + 1) == '\"') { cur.append('\"'); i++; }\n                    else inQuotes = false;\n                } else cur.append(c);\n            } else if (c == '\"') inQuotes = true;\n            else if (c == ',') { out.add(cur.toString()); cur.setLength(0); }\n            else cur.append(c);\n        }\n        out.add(cur.toString());\n        return out;\n    }\n}\n";
R["javi-p7-json-flat"] = "\nimport java.util.*;\n\npublic class Solution {\n    static String valueAfter(String json, String key) {\n        String needle = \"\\\"\" + key + \"\\\"\";\n        int k = json.indexOf(needle);\n        if (k < 0) return null;\n        int colon = json.indexOf(':', k + needle.length());\n        if (colon < 0) return null;\n        int i = colon + 1;\n        while (i < json.length() && Character.isWhitespace(json.charAt(i))) i++;\n        int end = i;\n        if (json.charAt(i) == '\"') {\n            end++;\n            while (json.charAt(end) != '\"') {\n                if (json.charAt(end) == '\\\\') end++;\n                end++;\n            }\n            return json.substring(i, end + 1);   // keep quotes; callers interpret\n        }\n        while (end < json.length() && \",}] \\n\\t\".indexOf(json.charAt(end)) < 0) end++;\n        return json.substring(i, end);\n    }\n\n    public static String str(String json, String key) {\n        String v = valueAfter(json, key);\n        if (v == null || !v.startsWith(\"\\\"\")) return null;\n        return v.substring(1, v.length() - 1);\n    }\n\n    public static Integer num(String json, String key) {\n        String v = valueAfter(json, key);\n        if (v == null || v.startsWith(\"\\\"\")) return null;\n        try { return Integer.parseInt(v); } catch (NumberFormatException e) { return null; }\n    }\n\n    public static Boolean bool(String json, String key) {\n        String v = valueAfter(json, key);\n        if (\"true\".equals(v)) return true;\n        if (\"false\".equals(v)) return false;\n        return null;\n    }\n}\n";
W["javi-p7-json-flat"] = "\nimport java.util.*;\n\npublic class Solution {\n    static String valueAfter(String json, String key) {\n        String needle = \"\\\"\" + key + \"\\\"\";\n        int k = json.indexOf(needle);\n        if (k < 0) return null;\n        int colon = json.indexOf(':', k + needle.length());\n        if (colon < 0) return null;\n        int i = colon + 1;\n        while (i < json.length() && Character.isWhitespace(json.charAt(i))) i++;\n        int end = i;\n        if (json.charAt(i) == '\"') {\n            end++;\n            while (json.charAt(end) != '\"') {\n                if (json.charAt(end) == '\\\\') end++;\n                end++;\n            }\n            return json.substring(i, end + 1);\n        }\n        while (end < json.length() && \",}] \\n\\t\".indexOf(json.charAt(end)) < 0) end++;\n        return json.substring(i, end);\n    }\n\n    // W: bool() reports true for any value starting with 't' \u2014 including\n    // the string \"taco\". Real booleans must match true/false exactly.\n    public static Boolean bool(String json, String key) {\n        String v = valueAfter(json, key);\n        if (v == null) return null;\n        return v.startsWith(\"t\");\n    }\n\n    public static String str(String json, String key) {\n        String v = valueAfter(json, key);\n        if (v == null || !v.startsWith(\"\\\"\")) return null;\n        return v.substring(1, v.length() - 1);\n    }\n\n    public static Integer num(String json, String key) {\n        String v = valueAfter(json, key);\n        if (v == null || v.startsWith(\"\\\"\")) return null;\n        try { return Integer.parseInt(v); } catch (NumberFormatException e) { return null; }\n    }\n}\n";
R["javi-checkpoint-m7-io"] = "\nimport java.util.*;\n\npublic class Solution {\n    public record Record(String name, int qty) {}\n\n    public static List<String> parseRow(String line) {\n        List<String> out = new ArrayList<>();\n        StringBuilder cur = new StringBuilder();\n        boolean inQuotes = false;\n        for (int i = 0; i < line.length(); i++) {\n            char c = line.charAt(i);\n            if (inQuotes) {\n                if (c == '\"') {\n                    if (i + 1 < line.length() && line.charAt(i + 1) == '\"') { cur.append('\"'); i++; }\n                    else inQuotes = false;\n                } else cur.append(c);\n            } else if (c == '\"') inQuotes = true;\n            else if (c == ',') { out.add(cur.toString()); cur.setLength(0); }\n            else cur.append(c);\n        }\n        out.add(cur.toString());\n        return out;\n    }\n\n    public static List<Record> normalize(List<String> rows, String header) {\n        List<Record> out = new ArrayList<>();\n        for (String row : rows) {\n            if (row.equals(header)) continue;\n            List<String> fields = parseRow(row);\n            if (fields.size() < 2) continue;\n            try {\n                out.add(new Record(fields.get(0), Integer.parseInt(fields.get(1).trim())));\n            } catch (NumberFormatException ignored) {\n                // skip malformed qty rows \u2014 documented behavior\n            }\n        }\n        return out;\n    }\n}\n";
W["javi-checkpoint-m7-io"] = "\nimport java.util.*;\n\npublic class Solution {\n    public record Record(String name, int qty) {}\n\n    public static List<String> parseRow(String line) {\n        List<String> out = new ArrayList<>();\n        StringBuilder cur = new StringBuilder();\n        boolean inQuotes = false;\n        for (int i = 0; i < line.length(); i++) {\n            char c = line.charAt(i);\n            if (inQuotes) {\n                if (c == '\"') {\n                    if (i + 1 < line.length() && line.charAt(i + 1) == '\"') { cur.append('\"'); i++; }\n                    else inQuotes = false;\n                } else cur.append(c);\n            } else if (c == '\"') inQuotes = true;\n            else if (c == ',') { out.add(cur.toString()); cur.setLength(0); }\n            else cur.append(c);\n        }\n        out.add(cur.toString());\n        return out;\n    }\n\n    // W: uses naive split for normalize (not the scanner), so quoted\n    // commas split the name field; also treats bad qty as fatal.\n    public static List<Record> normalize(List<String> rows, String header) {\n        List<Record> out = new ArrayList<>();\n        for (String row : rows) {\n            if (row.equals(header)) continue;\n            String[] fields = row.split(\",\");\n            out.add(new Record(fields[0], Integer.parseInt(fields[1].trim())));\n        }\n        return out;\n    }\n}\n";
R["javi-p8-frozen-clock"] = "\nimport java.time.*;\n\npublic class Solution {\n    public interface Clock { Instant now(); }\n\n    public static class Trial {\n        private final Clock clock;\n        public Trial(Clock clock) { this.clock = clock; }\n        public boolean isActive(Instant start, Instant end) {\n            Instant now = clock.now();\n            return !now.isBefore(start) && now.isBefore(end);\n        }\n    }\n\n    public static Clock frozenAt(String iso) {\n        Instant pinned = Instant.parse(iso);\n        return () -> pinned;\n    }\n}\n";
W["javi-p8-frozen-clock"] = "\nimport java.time.*;\n\npublic class Solution {\n    public interface Clock { Instant now(); }\n\n    public static class Trial {\n        private final Clock clock;\n        public Trial(Clock clock) { this.clock = clock; }\n        // W: strict start comparison \u2014 a trial is reported inactive at\n        // its exact start instant (now.isAfter(start) excludes equality).\n        public boolean isActive(Instant start, Instant end) {\n            Instant now = clock.now();\n            return now.isAfter(start) && now.isBefore(end);\n        }\n    }\n\n    public static Clock frozenAt(String iso) {\n        Instant pinned = Instant.parse(iso);\n        return () -> pinned;\n    }\n}\n";
R["javi-p8-boundary-net"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static int clamp(int v, int lo, int hi) {\n        return Math.max(lo, Math.min(v, hi));\n    }\n\n    public static List<String> selfCheck() {\n        List<String> net = new ArrayList<>();\n        if (clamp(5, 10, 20) == 10) net.add(\"low\");\n        if (clamp(25, 10, 20) == 20) net.add(\"high\");\n        if (clamp(15, 10, 20) == 15) net.add(\"in-range\");\n        if (clamp(10, 10, 20) == 10 && clamp(20, 10, 20) == 20) net.add(\"identity-at-bounds\");\n        return net;\n    }\n}\n";
W["javi-p8-boundary-net"] = "\nimport java.util.*;\n\npublic class Solution {\n    // W: clamp floors at lo but never caps at hi \u2014 every above-hi test\n    // in the net catches it (and selfCheck honestly omits \"high\").\n    public static int clamp(int v, int lo, int hi) {\n        return Math.max(lo, v);\n    }\n\n    public static List<String> selfCheck() {\n        List<String> net = new ArrayList<>();\n        if (clamp(5, 10, 20) == 10) net.add(\"low\");\n        if (clamp(25, 10, 20) == 20) net.add(\"high\");\n        if (clamp(15, 10, 20) == 15) net.add(\"in-range\");\n        if (clamp(10, 10, 20) == 10 && clamp(20, 10, 20) == 20) net.add(\"identity-at-bounds\");\n        return net;\n    }\n}\n";
R["javi-p8-order-blind"] = "\nimport java.util.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public static Set<String> uniqueTags(String csv) {\n        return Arrays.stream(csv.split(\",\"))\n            .map(String::trim)\n            .filter(s -> !s.isEmpty())\n            .collect(Collectors.toSet());\n    }\n\n    public static boolean sameContent(List<String> a, List<String> b) {\n        if (a == null || b == null) return a == b;\n        List<String> sa = new ArrayList<>(a), sb = new ArrayList<>(b);\n        Collections.sort(sa);\n        Collections.sort(sb);\n        return sa.equals(sb);\n    }\n}\n";
W["javi-p8-order-blind"] = "\nimport java.util.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public static Set<String> uniqueTags(String csv) {\n        return Arrays.stream(csv.split(\",\"))\n            .map(String::trim)\n            .filter(s -> !s.isEmpty())\n            .collect(Collectors.toSet());\n    }\n\n    // W: sameContent compares lists positionally \u2014 order-sensitive, so\n    // [\"x\",\"y\"] vs [\"y\",\"x\"] wrongly reports false. The order-blind\n    // contract is the whole point.\n    public static boolean sameContent(List<String> a, List<String> b) {\n        if (a == null || b == null) return a == b;\n        return a.equals(b);\n    }\n}\n";
R["javi-checkpoint-m8-testing"] = "\nimport java.util.*;\n\npublic class Solution {\n    public interface Clock { long nowMillis(); }\n    public interface AdvanceableClock extends Clock { void advance(long ms); }\n\n    public static AdvanceableClock manualClock(long startMillis) {\n        return new AdvanceableClock() {\n            private long now = startMillis;\n            public long nowMillis() { return now; }\n            public void advance(long ms) { now += ms; }\n        };\n    }\n\n    public static class RateLimiter {\n        private final Clock clock;\n        private final int maxPerWindow;\n        private final Map<String, List<Long>> calls = new HashMap<>();\n\n        public RateLimiter(Clock clock, int maxPerWindow) {\n            this.clock = clock;\n            this.maxPerWindow = maxPerWindow;\n        }\n\n        public boolean allow(String key) {\n            long now = clock.nowMillis();\n            List<Long> stamps = calls.computeIfAbsent(key, k -> new ArrayList<>());\n            stamps.removeIf(t -> now - t >= 1000);\n            if (stamps.size() >= maxPerWindow) return false;\n            stamps.add(now);\n            return true;\n        }\n    }\n}\n";
W["javi-checkpoint-m8-testing"] = "\nimport java.util.*;\n\npublic class Solution {\n    public interface Clock { long nowMillis(); }\n    public interface AdvanceableClock extends Clock { void advance(long ms); }\n\n    public static AdvanceableClock manualClock(long startMillis) {\n        return new AdvanceableClock() {\n            private long now = startMillis;\n            public long nowMillis() { return now; }\n            public void advance(long ms) { now += ms; }\n        };\n    }\n\n    public static class RateLimiter {\n        private final Clock clock;\n        private final int maxPerWindow;\n        private final Map<String, List<Long>> calls = new HashMap<>();\n\n        public RateLimiter(Clock clock, int maxPerWindow) {\n            this.clock = clock;\n            this.maxPerWindow = maxPerWindow;\n        }\n\n        // W: expiry never runs (removeIf guarded by an always-false\n        // condition), so old calls block forever \u2014 the rolling window\n        // is the entire feature.\n        public boolean allow(String key) {\n            long now = clock.nowMillis();\n            List<Long> stamps = calls.computeIfAbsent(key, k -> new ArrayList<>());\n            if (false) stamps.removeIf(t -> now - t >= 1000);\n            if (stamps.size() >= maxPerWindow) return false;\n            stamps.add(now);\n            return true;\n        }\n    }\n}\n";
R["javi-p9-safe-counter"] = "\nimport java.lang.reflect.*;\nimport java.util.concurrent.atomic.*;\n\npublic class Solution {\n    public static class RacyCounter {\n        long count = 0;\n        public void inc() { count++; }\n        public long value() { return count; }\n    }\n\n    public static class SafeCounter {\n        private final AtomicLong count = new AtomicLong();\n        public void inc() { count.incrementAndGet(); }\n        public long value() { return count.get(); }\n    }\n\n    public static long hammer(Object counter, int threads, int perThread) throws Exception {\n        Thread[] ts = new Thread[threads];\n        for (int i = 0; i < threads; i++) {\n            ts[i] = new Thread(() -> {\n                try {\n                    Method inc = counter.getClass().getMethod(\"inc\");\n                    for (int j = 0; j < perThread; j++) inc.invoke(counter);\n                } catch (Exception e) { throw new RuntimeException(e); }\n            });\n            ts[i].start();\n        }\n        for (Thread t : ts) t.join();\n        Method value = counter.getClass().getMethod(\"value\");\n        return (Long) value.invoke(counter);\n    }\n}\n";
W["javi-p9-safe-counter"] = "\nimport java.lang.reflect.*;\nimport java.util.concurrent.atomic.*;\n\npublic class Solution {\n    public static class RacyCounter {\n        long count = 0;\n        public void inc() { count++; }\n        public long value() { return count; }\n    }\n\n    public static class SafeCounter {\n        private final AtomicLong count = new AtomicLong();\n        // W: get-then-set is two atomic ops, not one \u2014 under contention\n        // two threads read the same value and one increment is lost.\n        public void inc() { count.set(count.get() + 1); }\n        public long value() { return count.get(); }\n    }\n\n    public static long hammer(Object counter, int threads, int perThread) throws Exception {\n        Thread[] ts = new Thread[threads];\n        for (int i = 0; i < threads; i++) {\n            ts[i] = new Thread(() -> {\n                try {\n                    Method inc = counter.getClass().getMethod(\"inc\");\n                    for (int j = 0; j < perThread; j++) inc.invoke(counter);\n                } catch (Exception e) { throw new RuntimeException(e); }\n            });\n            ts[i].start();\n        }\n        for (Thread t : ts) t.join();\n        Method value = counter.getClass().getMethod(\"value\");\n        return (Long) value.invoke(counter);\n    }\n}\n";
R["javi-p9-parallel-sum"] = "\npublic class Solution {\n    public static long parallelSum(int[] data, int parts) {\n        if (data == null || data.length == 0 || parts <= 0) return 0L;\n        int n = data.length;\n        int base = n / parts, rem = n % parts;\n        long[] sums = new long[parts];\n        Thread[] ts = new Thread[parts];\n        int offset = 0;\n        for (int p = 0; p < parts; p++) {\n            int len = base + (p < rem ? 1 : 0);\n            final int start = offset, end = offset + len;\n            final int idx = p;\n            ts[p] = new Thread(() -> {\n                long s = 0;\n                for (int i = start; i < end; i++) s += data[i];\n                sums[idx] = s;\n            });\n            ts[p].start();\n            offset += len;\n        }\n        long total = 0;\n        for (int p = 0; p < parts; p++) {\n            try { ts[p].join(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n            total += sums[p];\n        }\n        return total;\n    }\n}\n";
W["javi-p9-parallel-sum"] = "\npublic class Solution {\n    // W: reads sums[] without joining first \u2014 the combine loop races the\n    // workers, so totals are often short. The join-before-read edge is\n    // exactly what was missing.\n    public static long parallelSum(int[] data, int parts) {\n        if (data == null || data.length == 0 || parts <= 0) return 0L;\n        int n = data.length;\n        int base = n / parts, rem = n % parts;\n        long[] sums = new long[parts];\n        Thread[] ts = new Thread[parts];\n        int offset = 0;\n        for (int p = 0; p < parts; p++) {\n            int len = base + (p < rem ? 1 : 0);\n            final int start = offset, end = offset + len;\n            final int idx = p;\n            ts[p] = new Thread(() -> {\n                long s = 0;\n                for (int i = start; i < end; i++) s += data[i];\n                sums[idx] = s;\n            });\n            ts[p].start();\n            offset += len;\n        }\n        long total = 0;\n        for (int p = 0; p < parts; p++) total += sums[p];\n        return total;\n    }\n}\n";
R["javi-p9-latch-fanout"] = "\nimport java.util.*;\nimport java.util.concurrent.*;\n\npublic class Solution {\n    public static List<String> fanOut(int n) {\n        if (n <= 0) return new ArrayList<>();\n        CountDownLatch done = new CountDownLatch(n);\n        List<String> out = Collections.synchronizedList(new ArrayList<>());\n        for (int i = 0; i < n; i++) {\n            final int idx = i;\n            new Thread(() -> {\n                out.add(\"t\" + idx);\n                done.countDown();\n            }).start();\n        }\n        try { done.await(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n        Collections.sort(out);\n        return out;\n    }\n}\n";
W["javi-p9-latch-fanout"] = "\nimport java.util.*;\nimport java.util.concurrent.*;\n\npublic class Solution {\n    // W: awaits a latch that only decrements n-1 times \u2014 await() blocks\n    // forever and the test times out. Off-by-one in synchronization is a\n    // deadlock class of bug.\n    public static List<String> fanOut(int n) {\n        if (n <= 0) return new ArrayList<>();\n        CountDownLatch done = new CountDownLatch(n);\n        List<String> out = Collections.synchronizedList(new ArrayList<>());\n        for (int i = 0; i < n; i++) {\n            final int idx = i;\n            new Thread(() -> {\n                out.add(\"t\" + idx);\n                if (idx > 0) done.countDown();\n            }).start();\n        }\n        try { done.await(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n        Collections.sort(out);\n        return out;\n    }\n}\n";
R["javi-checkpoint-m9-concurrency"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static Map<String, Integer> countWords(List<String> chunks, int threads) {\n        Map<String, Integer> out = new HashMap<>();\n        if (chunks == null || chunks.isEmpty() || threads <= 0) return out;\n        int n = chunks.size();\n        int t = Math.min(threads, n);\n        int base = n / t, rem = n % t;\n        List<Map<String, Integer>> locals = new ArrayList<>();\n        Thread[] ts = new Thread[t];\n        int offset = 0;\n        for (int i = 0; i < t; i++) {\n            int len = base + (i < rem ? 1 : 0);\n            final int start = offset, end = offset + len;\n            locals.add(new HashMap<>());\n            final Map<String, Integer> local = locals.get(i);\n            ts[i] = new Thread(() -> {\n                for (int c = start; c < end; c++) {\n                    for (String w : chunks.get(c).split(\"\\\\s+\")) {\n                        local.merge(w, 1, Integer::sum);\n                    }\n                }\n            });\n            ts[i].start();\n            offset += len;\n        }\n        for (Thread th : ts) {\n            try { th.join(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n        }\n        for (Map<String, Integer> local : locals)\n            local.forEach((k, v) -> out.merge(k, v, Integer::sum));\n        return out;\n    }\n}\n";
W["javi-checkpoint-m9-concurrency"] = "\nimport java.util.*;\n\npublic class Solution {\n    // W: the final merge uses put() instead of merge-with-sum \u2014 when two\n    // thread-local maps share a key, the second OVERWRITES the first\n    // instead of adding. Deterministic loss whenever a word spans chunks.\n    public static Map<String, Integer> countWords(List<String> chunks, int threads) {\n        Map<String, Integer> out = new HashMap<>();\n        if (chunks == null || chunks.isEmpty() || threads <= 0) return out;\n        int n = chunks.size();\n        int t = Math.min(threads, n);\n        int base = n / t, rem = n % t;\n        List<Map<String, Integer>> locals = new ArrayList<>();\n        Thread[] ts = new Thread[t];\n        int offset = 0;\n        for (int i = 0; i < t; i++) {\n            int len = base + (i < rem ? 1 : 0);\n            final int start = offset, end = offset + len;\n            locals.add(new HashMap<>());\n            final Map<String, Integer> local = locals.get(i);\n            ts[i] = new Thread(() -> {\n                for (int c = start; c < end; c++) {\n                    for (String w : chunks.get(c).split(\"\\\\s+\")) {\n                        local.merge(w, 1, Integer::sum);\n                    }\n                }\n            });\n            ts[i].start();\n            offset += len;\n        }\n        for (Thread th : ts) {\n            try { th.join(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n        }\n        for (Map<String, Integer> local : locals) out.putAll(local);\n        return out;\n    }\n}\n";
R["javi-p10-cf-chain"] = "\nimport java.util.concurrent.*;\n\npublic class Solution {\n    public static CompletableFuture<Integer> pipeline(int base) {\n        return CompletableFuture.completedFuture(base)\n            .thenApply(x -> x * 2)\n            .thenApply(x -> x + 1);\n    }\n\n    public static CompletableFuture<Integer> combine(int a, int b) {\n        return pipeline(a).thenCombine(pipeline(b), Integer::sum);\n    }\n\n    public static CompletableFuture<Integer> safeDivide(int a, int b) {\n        return CompletableFuture.completedFuture(a)\n            .thenApply(x -> x / b)\n            .exceptionally(ex -> -1);\n    }\n}\n";
W["javi-p10-cf-chain"] = "\nimport java.util.concurrent.*;\n\npublic class Solution {\n    public static CompletableFuture<Integer> pipeline(int base) {\n        return CompletableFuture.completedFuture(base)\n            .thenApply(x -> x * 2)\n            .thenApply(x -> x + 1);\n    }\n\n    public static CompletableFuture<Integer> combine(int a, int b) {\n        return pipeline(a).thenCombine(pipeline(b), Integer::sum);\n    }\n\n    // W: division happens OUTSIDE the chain \u2014 ArithmeticException escapes\n    // the pipeline entirely, so exceptionally never runs and join() throws.\n    public static CompletableFuture<Integer> safeDivide(int a, int b) {\n        return CompletableFuture.completedFuture(a / b)\n            .exceptionally(ex -> -1);\n    }\n}\n";
R["javi-p10-transport"] = "\nimport java.util.*;\n\npublic class Solution {\n    public record HttpReply(int status, String body) {}\n    public interface HttpTransport { HttpReply send(String url); }\n\n    public static class ApiClient {\n        private final HttpTransport t;\n        public ApiClient(HttpTransport t) { this.t = t; }\n\n        public String fetchUser(String id) {\n            HttpReply res = t.send(\"https://api.test/users/\" + id);\n            if (res.status() == 200) return res.body();\n            if (res.status() == 404) throw new java.util.NoSuchElementException(\"user \" + id);\n            throw new IllegalStateException(\"server error \" + res.status());\n        }\n    }\n\n    public static HttpTransport fakeTransport(Map<String, HttpReply> replies) {\n        return url -> replies.getOrDefault(url, new HttpReply(404, \"\"));\n    }\n}\n";
W["javi-p10-transport"] = "\nimport java.util.*;\n\npublic class Solution {\n    public record HttpReply(int status, String body) {}\n    public interface HttpTransport { HttpReply send(String url); }\n\n    public static class ApiClient {\n        private final HttpTransport t;\n        public ApiClient(HttpTransport t) { this.t = t; }\n\n        // W: treats any non-404 as success and returns the raw status as\n        // the body \u2014 200 responses lose their real body and 5xx never\n        // becomes an error.\n        public String fetchUser(String id) {\n            HttpReply res = t.send(\"https://api.test/users/\" + id);\n            if (res.status() == 404) throw new java.util.NoSuchElementException(\"user \" + id);\n            return String.valueOf(res.status());\n        }\n    }\n\n    public static HttpTransport fakeTransport(Map<String, HttpReply> replies) {\n        return url -> replies.getOrDefault(url, new HttpReply(404, \"\"));\n    }\n}\n";
R["javi-p10-retry"] = "\npublic class Solution {\n    public interface FlakyTransport { int attempt(String url); }\n\n    public static int attemptsToSucceed(FlakyTransport t, String url) {\n        int maxCalls = 4;   // 1 initial + 3 retries\n        for (int attempt = 1; attempt <= maxCalls; attempt++) {\n            int status = t.attempt(url);\n            if (status == 200) return attempt;\n            if (status >= 400 && status < 500) return -1;   // client error, no retry\n        }\n        return -1;\n    }\n}\n";
W["javi-p10-retry"] = "\npublic class Solution {\n    public interface FlakyTransport { int attempt(String url); }\n\n    // W: retries 4xx like 5xx \u2014 burns all four calls on a permanent\n    // client error before giving up. Policy bug the call-count test\n    // catches instantly.\n    public static int attemptsToSucceed(FlakyTransport t, String url) {\n        int maxCalls = 4;\n        for (int attempt = 1; attempt <= maxCalls; attempt++) {\n            int status = t.attempt(url);\n            if (status == 200) return attempt;\n        }\n        return -1;\n    }\n}\n";
R["javi-checkpoint-m10-async"] = "\nimport java.util.*;\nimport java.util.concurrent.*;\n\npublic class Solution {\n    public interface Shard { int fetch(String key); }\n\n    public static int totalFromAll(List<Shard> shards, String key) {\n        int total = 0;\n        for (Shard s : shards) {\n            try { total += s.fetch(key); } catch (RuntimeException ignored) { }\n        }\n        return total;\n    }\n\n    public static CompletableFuture<Integer> asyncTotal(List<Shard> shards, String key) {\n        List<CompletableFuture<Integer>> futures = new ArrayList<>();\n        for (Shard s : shards) {\n            futures.add(CompletableFuture.completedFuture(s)\n                .thenApply(sh -> sh.fetch(key))\n                .exceptionally(ex -> 0));\n        }\n        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))\n            .thenApply(v -> futures.stream().mapToInt(CompletableFuture::join).sum());\n    }\n}\n";
W["javi-checkpoint-m10-async"] = "\nimport java.util.*;\nimport java.util.concurrent.*;\n\npublic class Solution {\n    public interface Shard { int fetch(String key); }\n\n    // W: one bad shard aborts the whole aggregation \u2014 no fault isolation,\n    // so a single failure poisons every result.\n    public static int totalFromAll(List<Shard> shards, String key) {\n        int total = 0;\n        for (Shard s : shards) total += s.fetch(key);\n        return total;\n    }\n\n    public static CompletableFuture<Integer> asyncTotal(List<Shard> shards, String key) {\n        List<CompletableFuture<Integer>> futures = new ArrayList<>();\n        for (Shard s : shards) {\n            futures.add(CompletableFuture.completedFuture(s)\n                .thenApply(sh -> sh.fetch(key))\n                .exceptionally(ex -> 0));\n        }\n        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))\n            .thenApply(v -> futures.stream().mapToInt(CompletableFuture::join).sum());\n    }\n}\n";
R["javi-p11-expense-repo"] = "\nimport java.util.*;\n\npublic class Solution {\n    public record Expense(String id, String category, int cents) {}\n    public static class DuplicateExpenseException extends RuntimeException {\n        public DuplicateExpenseException(String m) { super(m); }\n    }\n\n    public static class ExpenseRepository {\n        private final Map<String, Expense> store = new LinkedHashMap<>();\n\n        public Expense save(Expense e) {\n            Expense old = store.get(e.id());\n            if (old != null && !old.category().equals(e.category())) {\n                throw new DuplicateExpenseException(\"id conflict: \" + e.id());\n            }\n            store.put(e.id(), e);\n            return e;\n        }\n        public Optional<Expense> findById(String id) { return Optional.ofNullable(store.get(id)); }\n        public List<Expense> findByCategory(String category) {\n            List<Expense> out = new ArrayList<>();\n            for (Expense e : store.values()) if (e.category().equals(category)) out.add(e);\n            return out;\n        }\n        public boolean deleteById(String id) { return store.remove(id) != null; }\n        public List<Expense> findAll() { return new ArrayList<>(store.values()); }\n        public int totalCents() {\n            int t = 0;\n            for (Expense e : store.values()) t += e.cents();\n            return t;\n        }\n    }\n}\n";
W["javi-p11-expense-repo"] = "\nimport java.util.*;\n\npublic class Solution {\n    public record Expense(String id, String category, int cents) {}\n    public static class DuplicateExpenseException extends RuntimeException {\n        public DuplicateExpenseException(String m) { super(m); }\n    }\n\n    public static class ExpenseRepository {\n        private final Map<String, Expense> store = new LinkedHashMap<>();\n\n        public Expense save(Expense e) {\n            // W: rejects ALL re-saves including legitimate same-category\n            // updates \u2014 an upsert API must allow amount changes.\n            Expense old = store.get(e.id());\n            if (old != null) throw new DuplicateExpenseException(\"id conflict: \" + e.id());\n            store.put(e.id(), e);\n            return e;\n        }\n        public Optional<Expense> findById(String id) { return Optional.ofNullable(store.get(id)); }\n        public List<Expense> findByCategory(String category) {\n            List<Expense> out = new ArrayList<>();\n            for (Expense e : store.values()) if (e.category().equals(category)) out.add(e);\n            return out;\n        }\n        public boolean deleteById(String id) { return store.remove(id) != null; }\n        public List<Expense> findAll() { return new ArrayList<>(store.values()); }\n        public int totalCents() {\n            int t = 0;\n            for (Expense e : store.values()) t += e.cents();\n            return t;\n        }\n    }\n}\n";
R["javi-p11-safe-queries"] = "\npublic class Solution {\n    public record Param(String value) {}\n\n    public static String buildFind(String table, Param id) {\n        return \"SELECT * FROM \" + table + \" WHERE id = ?\";\n    }\n\n    public static String buildFindUnsafe(String table, String id) {\n        return \"SELECT * FROM \" + table + \" WHERE id = '\" + id + \"'\";\n    }\n}\n";
W["javi-p11-safe-queries"] = "\npublic class Solution {\n    public record Param(String value) {}\n\n    // W: \"safe\" builder interpolates the raw value into the SQL text \u2014\n    // identical to buildFindUnsafe. The ? placeholder only protects when\n    // the value is actually bound at execution time.\n    public static String buildFind(String table, Param id) {\n        return \"SELECT * FROM \" + table + \" WHERE id = '\" + id.value() + \"'\";\n    }\n\n    public static String buildFindUnsafe(String table, String id) {\n        return \"SELECT * FROM \" + table + \" WHERE id = '\" + id + \"'\";\n    }\n}\n";
R["javi-p11-index-sync"] = "\nimport java.util.*;\n\npublic class Solution {\n    public record Book(String isbn, String genre) {}\n\n    public static class IndexedStore {\n        private final Map<String, Book> books = new LinkedHashMap<>();\n        private final Map<String, List<Book>> byGenre = new HashMap<>();\n\n        public void save(Book b) {\n            Book old = books.put(b.isbn(), b);\n            if (old != null) {\n                List<Book> bucket = byGenre.get(old.genre());\n                if (bucket != null) bucket.remove(old);\n            }\n            byGenre.computeIfAbsent(b.genre(), k -> new ArrayList<>()).add(b);\n        }\n\n        public List<Book> byGenre(String genre) {\n            return new ArrayList<>(byGenre.getOrDefault(genre, List.of()));\n        }\n\n        public boolean remove(String isbn) {\n            Book old = books.remove(isbn);\n            if (old == null) return false;\n            List<Book> bucket = byGenre.get(old.genre());\n            if (bucket != null) bucket.remove(old);\n            return true;\n        }\n\n        public int size() { return books.size(); }\n    }\n}\n";
W["javi-p11-index-sync"] = "\nimport java.util.*;\n\npublic class Solution {\n    public record Book(String isbn, String genre) {}\n\n    public static class IndexedStore {\n        private final Map<String, Book> books = new LinkedHashMap<>();\n        private final Map<String, List<Book>> byGenre = new HashMap<>();\n\n        // W: main store updated, index ignored on genre change \u2014 the\n        // stale-index bug from the lesson verbatim. The book stays in\n        // its OLD genre bucket forever.\n        public void save(Book b) {\n            books.put(b.isbn(), b);\n            byGenre.computeIfAbsent(b.genre(), k -> new ArrayList<>()).add(b);\n        }\n\n        public List<Book> byGenre(String genre) {\n            return new ArrayList<>(byGenre.getOrDefault(genre, List.of()));\n        }\n\n        public boolean remove(String isbn) {\n            Book old = books.remove(isbn);\n            if (old == null) return false;\n            List<Book> bucket = byGenre.get(old.genre());\n            if (bucket != null) bucket.remove(old);\n            return true;\n        }\n\n        public int size() { return books.size(); }\n    }\n}\n";
R["javi-checkpoint-m11-persistence"] = "\nimport java.util.*;\nimport java.util.function.Consumer;\n\npublic class Solution {\n    public record OutboxEntry(String id, String topic, String payload) {}\n\n    public static class OutboxStore {\n        private final List<OutboxEntry> entries = new ArrayList<>();\n\n        public boolean offer(OutboxEntry e) {\n            for (OutboxEntry existing : entries) {\n                if (existing.id().equals(e.id())) return false;\n            }\n            entries.add(e);\n            return true;\n        }\n\n        public List<OutboxEntry> drain(String topic) {\n            List<OutboxEntry> out = new ArrayList<>();\n            Iterator<OutboxEntry> it = entries.iterator();\n            while (it.hasNext()) {\n                OutboxEntry e = it.next();\n                if (e.topic().equals(topic)) { out.add(e); it.remove(); }\n            }\n            return out;\n        }\n\n        public int pending() { return entries.size(); }\n    }\n\n    public static int deliverAll(OutboxStore store, String topic, Consumer<OutboxEntry> sink) {\n        List<OutboxEntry> batch = store.drain(topic);\n        for (OutboxEntry e : batch) sink.accept(e);\n        return batch.size();\n    }\n}\n";
W["javi-checkpoint-m11-persistence"] = "\nimport java.util.*;\nimport java.util.function.Consumer;\n\npublic class Solution {\n    public record OutboxEntry(String id, String topic, String payload) {}\n\n    public static class OutboxStore {\n        private final List<OutboxEntry> entries = new ArrayList<>();\n\n        // W: offer accepts duplicates \u2014 the exactly-once guarantee is\n        // gone and the deliverAll test counts two deliveries.\n        public boolean offer(OutboxEntry e) {\n            entries.add(e);\n            return true;\n        }\n\n        public List<OutboxEntry> drain(String topic) {\n            List<OutboxEntry> out = new ArrayList<>();\n            Iterator<OutboxEntry> it = entries.iterator();\n            while (it.hasNext()) {\n                OutboxEntry e = it.next();\n                if (e.topic().equals(topic)) { out.add(e); it.remove(); }\n            }\n            return out;\n        }\n\n        public int pending() { return entries.size(); }\n    }\n\n    public static int deliverAll(OutboxStore store, String topic, Consumer<OutboxEntry> sink) {\n        List<OutboxEntry> batch = store.drain(topic);\n        for (OutboxEntry e : batch) sink.accept(e);\n        return batch.size();\n    }\n}\n";
R["javi-p12-checkout-layers"] = "\npublic class Solution {\n    public record Order(String id, int cents) {}\n    public record OrderView(String id, String total) {}\n\n    public interface OrderRepository {\n        void save(Order o);\n        Order findById(String id);\n    }\n\n    public static class InMemoryOrderRepository implements OrderRepository {\n        private final java.util.Map<String, Order> store = new java.util.LinkedHashMap<>();\n        public void save(Order o) { store.put(o.id(), o); }\n        public Order findById(String id) { return store.get(id); }\n    }\n\n    public static class CheckoutService {\n        private final OrderRepository r;\n        public CheckoutService(OrderRepository r) { this.r = r; }\n        public Order place(String id, int cents) {\n            if (cents < 0) throw new IllegalArgumentException(\"negative cents\");\n            Order o = new Order(id, cents);\n            r.save(o);\n            return o;\n        }\n    }\n\n    public static String viewTotal(int cents) {\n        return \"$\" + (cents / 100) + \".\" + String.format(\"%02d\", cents % 100);\n    }\n}\n";
W["javi-p12-checkout-layers"] = "\npublic class Solution {\n    public record Order(String id, int cents) {}\n    public record OrderView(String id, String total) {}\n\n    public interface OrderRepository {\n        void save(Order o);\n        Order findById(String id);\n    }\n\n    public static class InMemoryOrderRepository implements OrderRepository {\n        private final java.util.Map<String, Order> store = new java.util.LinkedHashMap<>();\n        public void save(Order o) { store.put(o.id(), o); }\n        public Order findById(String id) { return store.get(id); }\n    }\n\n    public static class CheckoutService {\n        private final OrderRepository r;\n        public CheckoutService(OrderRepository r) { this.r = r; }\n        // W: validation pushed down into the repository \u2014 business rules\n        // leak below the service boundary and the repo now throws on\n        // data the service should have guarded.\n        public Order place(String id, int cents) {\n            Order o = new Order(id, cents);\n            r.save(o);\n            return o;\n        }\n    }\n\n    public static String viewTotal(int cents) {\n        return \"$\" + (cents / 100) + \".\" + String.format(\"%02d\", cents % 100);\n    }\n}\n";
R["javi-p12-extract-pricing"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static class Pricing {\n        public static int total(List<Integer> centsList, int discountPercent) {\n            int sum = 0;\n            for (int c : centsList) sum += c;\n            return sum - sum * discountPercent / 100;\n        }\n    }\n\n    public static class GodCart {\n        public String receipt(List<Integer> centsList, int discountPercent) {\n            return \"TOTAL: $\" + Solution.viewTotal(Pricing.total(centsList, discountPercent)).substring(1);\n        }\n    }\n\n    public static String viewTotal(int cents) {\n        return \"$\" + (cents / 100) + \".\" + String.format(\"%02d\", cents % 100);\n    }\n}\n";
W["javi-p12-extract-pricing"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static class Pricing {\n        // W: the discount parameter is accepted and ignored \u2014 the receipt\n        // always shows the full sum. Every discounted expectation fails.\n        public static int total(List<Integer> centsList, int discountPercent) {\n            int sum = 0;\n            for (int c : centsList) sum += c;\n            return sum;\n        }\n    }\n\n    public static class GodCart {\n        public String receipt(List<Integer> centsList, int discountPercent) {\n            return \"TOTAL: $\" + Solution.viewTotal(Pricing.total(centsList, discountPercent)).substring(1);\n        }\n    }\n\n    public static String viewTotal(int cents) {\n        return \"$\" + (cents / 100) + \".\" + String.format(\"%02d\", cents % 100);\n    }\n}\n";
R["javi-p12-testable-report"] = "\npublic class Solution {\n    public interface Clock { long nowMillis(); }\n\n    public static class ReportService {\n        private final Clock clock;\n        public ReportService(Clock clock) { this.clock = clock; }\n        public String header() { return \"Report @ \" + clock.nowMillis(); }\n    }\n\n    public static class ReportController {\n        private final ReportService s;\n        public ReportController(ReportService s) { this.s = s; }\n        public String render() { return s.header() + \"\\n[body]\"; }\n    }\n}\n";
W["javi-p12-testable-report"] = "\npublic class Solution {\n    public interface Clock { long nowMillis(); }\n\n    public static class ReportService {\n        private final Clock clock;\n        public ReportService(Clock clock) { this.clock = clock; }\n        // W: the service calls System.currentTimeMillis() directly \u2014\n        // the injected clock is ignored, so both controllers print the\n        // same (real) time and the seam is dead.\n        public String header() { return \"Report @ \" + System.currentTimeMillis(); }\n    }\n\n    public static class ReportController {\n        private final ReportService s;\n        public ReportController(ReportService s) { this.s = s; }\n        public String render() { return s.header() + \"\\n[body]\"; }\n    }\n}\n";
R["javi-checkpoint-m12-architecture"] = "\nimport java.util.*;\n\npublic class Solution {\n    public record Task(String id, String title, boolean done) {}\n    public record TaskView(String id, String title) {}\n\n    public interface TaskRepository {\n        void save(Task t);\n        Optional<Task> find(String id);\n        List<Task> all();\n    }\n\n    public static class InMemoryTaskRepository implements TaskRepository {\n        private final Map<String, Task> store = new LinkedHashMap<>();\n        public void save(Task t) { store.put(t.id(), t); }\n        public Optional<Task> find(String id) { return Optional.ofNullable(store.get(id)); }\n        public List<Task> all() { return new ArrayList<>(store.values()); }\n    }\n\n    public static class TaskService {\n        private final TaskRepository r;\n        public TaskService(TaskRepository r) { this.r = r; }\n\n        public Task create(String id, String title) {\n            if (title == null || title.isBlank()) throw new IllegalArgumentException(\"blank title\");\n            Task t = new Task(id, title, false);\n            r.save(t);\n            return t;\n        }\n\n        public Task complete(String id) {\n            Task t = r.find(id).orElseThrow(() -> new NoSuchElementException(\"task \" + id));\n            Task done = new Task(t.id(), t.title(), true);\n            r.save(done);\n            return done;\n        }\n\n        public List<Task> pending() {\n            List<Task> out = new ArrayList<>();\n            for (Task t : r.all()) if (!t.done()) out.add(t);\n            return out;\n        }\n    }\n\n    public static List<TaskView> pendingViews(TaskService s) {\n        List<TaskView> out = new ArrayList<>();\n        for (Task t : s.pending()) out.add(new TaskView(t.id(), t.title()));\n        return out;\n    }\n}\n";
W["javi-checkpoint-m12-architecture"] = "\nimport java.util.*;\n\npublic class Solution {\n    public record Task(String id, String title, boolean done) {}\n    public record TaskView(String id, String title) {}\n\n    public interface TaskRepository {\n        void save(Task t);\n        Optional<Task> find(String id);\n        List<Task> all();\n    }\n\n    public static class InMemoryTaskRepository implements TaskRepository {\n        private final Map<String, Task> store = new LinkedHashMap<>();\n        public void save(Task t) { store.put(t.id(), t); }\n        public Optional<Task> find(String id) { return Optional.ofNullable(store.get(id)); }\n        public List<Task> all() { return new ArrayList<>(store.values()); }\n    }\n\n    public static class TaskService {\n        private final TaskRepository r;\n        public TaskService(TaskRepository r) { this.r = r; }\n\n        // W: complete() never saves the updated task \u2014 the state flip\n        // lives only in the returned object and the store still says\n        // not-done, so pending() keeps listing completed tasks.\n        public Task complete(String id) {\n            Task t = r.find(id).orElseThrow(() -> new NoSuchElementException(\"task \" + id));\n            return new Task(t.id(), t.title(), true);\n        }\n\n        public Task create(String id, String title) {\n            if (title == null || title.isBlank()) throw new IllegalArgumentException(\"blank title\");\n            Task t = new Task(id, title, false);\n            r.save(t);\n            return t;\n        }\n\n        public List<Task> pending() {\n            List<Task> out = new ArrayList<>();\n            for (Task t : r.all()) if (!t.done()) out.add(t);\n            return out;\n        }\n    }\n\n    public static List<TaskView> pendingViews(TaskService s) {\n        List<TaskView> out = new ArrayList<>();\n        for (Task t : s.pending()) out.add(new TaskView(t.id(), t.title()));\n        return out;\n    }\n}\n";
R["javi-p13-pair-sum"] = "\npublic class Solution {\n    public static int[] pairWithSum(int[] sorted, int target) {\n        if (sorted == null) return null;\n        int lo = 0, hi = sorted.length - 1;\n        while (lo < hi) {\n            int s = sorted[lo] + sorted[hi];\n            if (s == target) return new int[]{lo, hi};\n            if (s < target) lo++; else hi--;\n        }\n        return null;\n    }\n}\n";
W["javi-p13-pair-sum"] = "\npublic class Solution {\n    // W: returns the VALUES as if they were indices \u2014 on unsorted-input\n    // deployments this silently corrupts callers. Also fails the\n    // duplicates case: 3+3=6 reports [3,3] instead of [0,1].\n    public static int[] pairWithSum(int[] sorted, int target) {\n        if (sorted == null) return null;\n        int lo = 0, hi = sorted.length - 1;\n        while (lo < hi) {\n            int s = sorted[lo] + sorted[hi];\n            if (s == target) return new int[]{sorted[lo], sorted[hi]};\n            if (s < target) lo++; else hi--;\n        }\n        return null;\n    }\n}\n";
R["javi-p13-sliding-window"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static int longestWindow(int[] xs, int k) {\n        if (xs == null || xs.length == 0 || k <= 0) return 0;\n        Map<Integer, Integer> freq = new HashMap<>();\n        int left = 0, best = 0;\n        for (int right = 0; right < xs.length; right++) {\n            freq.merge(xs[right], 1, Integer::sum);\n            while (freq.size() > k) {\n                int out = freq.merge(xs[left], -1, Integer::sum);\n                if (out == 0) freq.remove(xs[left]);\n                left++;\n            }\n            best = Math.max(best, right - left + 1);\n        }\n        return best;\n    }\n}\n";
W["javi-p13-sliding-window"] = "\nimport java.util.*;\n\npublic class Solution {\n    // W: forgets to decrement the outgoing frequency \u2014 the map only ever\n    // grows, so the window never shrinks and the answer inflates to the\n    // longest run with AT MOST one distinct value... plus stale counts.\n    public static int longestWindow(int[] xs, int k) {\n        if (xs == null || xs.length == 0 || k <= 0) return 0;\n        Map<Integer, Integer> freq = new HashMap<>();\n        int left = 0, best = 0;\n        for (int right = 0; right < xs.length; right++) {\n            freq.merge(xs[right], 1, Integer::sum);\n            while (freq.size() > k) left++;   // map not updated!\n            best = Math.max(best, right - left + 1);\n        }\n        return best;\n    }\n}\n";
R["javi-p13-prefix-sum"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static long[] prefixSums(int[] xs) {\n        long[] pre = new long[xs.length + 1];\n        for (int i = 0; i < xs.length; i++) pre[i + 1] = pre[i] + xs[i];\n        return pre;\n    }\n\n    public static long rangeSum(long[] pre, int l, int r) {\n        return pre[r] - pre[l];\n    }\n\n    public static int countSubarraysWithSum(int[] xs, int target) {\n        Map<Long, Integer> seen = new HashMap<>();\n        seen.put(0L, 1);\n        long running = 0;\n        int count = 0;\n        for (int x : xs) {\n            running += x;\n            count += seen.getOrDefault(running - target, 0);\n            seen.merge(running, 1, Integer::sum);\n        }\n        return count;\n    }\n}\n";
W["javi-p13-prefix-sum"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static long[] prefixSums(int[] xs) {\n        long[] pre = new long[xs.length + 1];\n        for (int i = 0; i < xs.length; i++) pre[i + 1] = pre[i] + xs[i];\n        return pre;\n    }\n\n    public static long rangeSum(long[] pre, int l, int r) {\n        return pre[r] - pre[l];\n    }\n\n    // W: counts subarrays with sum AT LEAST target instead of EXACTLY \u2014\n    // every near-miss range inflates the count.\n    public static int countSubarraysWithSum(int[] xs, int target) {\n        int count = 0;\n        for (int i = 0; i < xs.length; i++) {\n            long s = 0;\n            for (int j = i; j < xs.length; j++) {\n                s += xs[j];\n                if (s >= target) count++;\n            }\n        }\n        return count;\n    }\n}\n";
R["javi-checkpoint-m13-algorithms"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static int lowerBound(int[] sorted, int target) {\n        int lo = 0, hi = sorted.length;\n        while (lo < hi) {\n            int mid = (lo + hi) >>> 1;\n            if (sorted[mid] >= target) hi = mid; else lo = mid + 1;\n        }\n        return lo;\n    }\n\n    public static boolean hasMajority(int[] xs) {\n        if (xs == null || xs.length == 0) return false;\n        Map<Integer, Integer> freq = new HashMap<>();\n        for (int x : xs) {\n            int c = freq.merge(x, 1, Integer::sum);\n            if (c * 2 > xs.length) return true;\n        }\n        return false;\n    }\n}\n";
W["javi-checkpoint-m13-algorithms"] = "\nimport java.util.*;\n\npublic class Solution {\n    // W: lowerBound returns the FIRST EQUAL match (like indexOf) \u2014 with\n    // duplicates it reports the first x == target, not the first\n    // x >= target, missing leftward qualifying values.\n    public static int lowerBound(int[] sorted, int target) {\n        for (int i = 0; i < sorted.length; i++) {\n            if (sorted[i] == target) return i;\n        }\n        return sorted.length;\n    }\n\n    public static boolean hasMajority(int[] xs) {\n        if (xs == null || xs.length == 0) return false;\n        Map<Integer, Integer> freq = new HashMap<>();\n        for (int x : xs) {\n            int c = freq.merge(x, 1, Integer::sum);\n            if (c * 2 > xs.length) return true;\n        }\n        return false;\n    }\n}\n";
R["javi-p14-guard-rename"] = "\npublic class Solution {\n    public static int shipFee(int weightGrams, boolean vip, String country) {\n        if (!\"VN\".equals(country) && !\"SG\".equals(country)) {\n            throw new IllegalArgumentException(\"unsupported country\");\n        }\n        if (weightGrams <= 0) throw new IllegalArgumentException(\"weight required\");\n        int feeCents = 400;\n        if (weightGrams > 2000) feeCents += 200;\n        if (vip) feeCents = feeCents / 2;\n        return feeCents;\n    }\n}\n";
W["javi-p14-guard-rename"] = "\npublic class Solution {\n    // W: vip discount applied to the BASE only, before the heavy\n    // surcharge \u2014 a VIP with a heavy parcel pays 400/2+200 = 400 instead\n    // of the correct 600/2 = 300. Wrong on the heavy-VIP row.\n    public static int shipFee(int weightGrams, boolean vip, String country) {\n        if (!\"VN\".equals(country) && !\"SG\".equals(country)) {\n            throw new IllegalArgumentException(\"unsupported country\");\n        }\n        if (weightGrams <= 0) throw new IllegalArgumentException(\"weight required\");\n        int feeCents = 400;\n        if (vip) feeCents = feeCents / 2;\n        if (weightGrams > 2000) feeCents += 200;\n        return feeCents;\n    }\n}\n";
R["javi-p14-value-object"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static class Email {\n        private final String value;\n        public Email(String raw) {\n            if (raw == null) throw new IllegalArgumentException(\"email required\");\n            String v = raw.trim().toLowerCase();\n            int at = v.indexOf('@');\n            if (at <= 0 || at != v.lastIndexOf('@')) throw new IllegalArgumentException(\"bad email\");\n            String local = v.substring(0, at);\n            String domain = v.substring(at + 1);\n            int dot = domain.lastIndexOf('.');\n            if (local.isEmpty() || domain.isEmpty() || dot < 1 || dot == domain.length() - 1) {\n                throw new IllegalArgumentException(\"bad email\");\n            }\n            this.value = v;\n        }\n        public String value() { return value; }\n    }\n\n    public static List<String> uniqueEmails(List<String> rawList) {\n        List<String> out = new ArrayList<>();\n        Set<String> seen = new HashSet<>();\n        for (String raw : rawList) {\n            try {\n                Email e = new Email(raw);\n                if (seen.add(e.value())) out.add(e.value());\n            } catch (IllegalArgumentException ignored) { }\n        }\n        return out;\n    }\n}\n";
W["javi-p14-value-object"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static class Email {\n        private final String value;\n        public Email(String raw) {\n            if (raw == null) throw new IllegalArgumentException(\"email required\");\n            String v = raw.trim().toLowerCase();\n            int at = v.indexOf('@');\n            if (at <= 0 || at != v.lastIndexOf('@')) throw new IllegalArgumentException(\"bad email\");\n            String local = v.substring(0, at);\n            String domain = v.substring(at + 1);\n            int dot = domain.lastIndexOf('.');\n            if (local.isEmpty() || domain.isEmpty() || dot < 1 || dot == domain.length() - 1) {\n                throw new IllegalArgumentException(\"bad email\");\n            }\n            this.value = v;\n        }\n        public String value() { return value; }\n    }\n\n    // W: uniqueEmails ignores parse failures and emits the RAW strings \u2014\n    // normalization and error-handling both skipped, so duplicates in\n    // different cases survive and garbage leaks through.\n    public static List<String> uniqueEmails(List<String> rawList) {\n        List<String> out = new ArrayList<>();\n        for (String raw : rawList) {\n            if (!out.contains(raw)) out.add(raw);\n        }\n        return out;\n    }\n}\n";
R["javi-p14-extract-statements"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static boolean isSuspicious(int cents) {\n        return Math.abs(cents) > 10000;\n    }\n\n    public static String describe(int cents) {\n        return cents >= 0 ? \"CREDIT \" + cents : \"DEBIT \" + (-cents);\n    }\n\n    public static List<String> auditLines(List<Integer> amountsCents) {\n        List<String> out = new ArrayList<>();\n        for (int a : amountsCents) {\n            String line = describe(a);\n            if (isSuspicious(a)) line += \" [SUSPECT]\";\n            out.add(line);\n        }\n        return out;\n    }\n}\n";
W["javi-p14-extract-statements"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static boolean isSuspicious(int cents) {\n        return Math.abs(cents) > 10000;\n    }\n\n    public static String describe(int cents) {\n        return cents >= 0 ? \"CREDIT \" + cents : \"DEBIT \" + (-cents);\n    }\n\n    // W: the SUSPECT threshold is re-hardcoded as 9999 here instead of\n    // calling isSuspicious \u2014 two thresholds now disagree, exactly the\n    // duplication the exercise removed.\n    public static List<String> auditLines(List<Integer> amountsCents) {\n        List<String> out = new ArrayList<>();\n        for (int a : amountsCents) {\n            String line = describe(a);\n            if (Math.abs(a) > 9999) line += \" [SUSPECT]\";\n            out.add(line);\n        }\n        return out;\n    }\n}\n";
R["javi-checkpoint-m14-clean"] = "\npublic class Solution {\n    public static boolean isValidId(String id) {\n        return id != null && id.length() >= 3 && id.length() <= 20;\n    }\n\n    public static boolean isValidAmount(int cents) {\n        return cents >= 1 && cents <= 1_000_000;\n    }\n\n    public static boolean isValidCoupon(String coupon) {\n        if (coupon == null || coupon.isEmpty()) return true;\n        return coupon.matches(\"[A-Z0-9]{4,10}\");\n    }\n\n    public static String validateOrder(String id, int cents, String coupon) {\n        if (!isValidId(id)) return \"BAD_ID\";\n        if (!isValidAmount(cents)) return \"BAD_AMOUNT\";\n        if (!isValidCoupon(coupon)) return \"BAD_COUPON\";\n        return \"OK\";\n    }\n}\n";
W["javi-checkpoint-m14-clean"] = "\npublic class Solution {\n    public static boolean isValidId(String id) {\n        return id != null && id.length() >= 3 && id.length() <= 20;\n    }\n\n    public static boolean isValidAmount(int cents) {\n        return cents >= 1 && cents <= 1_000_000;\n    }\n\n    public static boolean isValidCoupon(String coupon) {\n        if (coupon == null || coupon.isEmpty()) return true;\n        return coupon.matches(\"[A-Z0-9]{4,10}\");\n    }\n\n    // W: checks the coupon BEFORE the amount \u2014 wrong precedence, so a\n    // request with both an empty amount and a bad coupon reports\n    // BAD_COUPON instead of BAD_AMOUNT.\n    public static String validateOrder(String id, int cents, String coupon) {\n        if (!isValidId(id)) return \"BAD_ID\";\n        if (!isValidCoupon(coupon)) return \"BAD_COUPON\";\n        if (!isValidAmount(cents)) return \"BAD_AMOUNT\";\n        return \"OK\";\n    }\n}\n";
R["javi-p15-expense-domain"] = "\npublic class Solution {\n    public static class InvalidExpenseException extends RuntimeException {\n        private final String problem;\n        public InvalidExpenseException(String problem) {\n            super(problem);\n            this.problem = problem;\n        }\n        public String problem() { return problem; }\n    }\n\n    public record Expense(String id, String category, int cents) {\n        public Expense {\n            // Records give value semantics: correct equals/hashCode for\n            // free \u2014 that's WHY no manual contract code is needed here.\n            if (id == null || id.isBlank()) throw new InvalidExpenseException(\"blank id\");\n            if (category == null || category.isBlank()) throw new InvalidExpenseException(\"blank category\");\n            if (cents <= 0) throw new InvalidExpenseException(\"non-positive cents\");\n        }\n    }\n}\n";
W["javi-p15-expense-domain"] = "\npublic class Solution {\n    public static class InvalidExpenseException extends RuntimeException {\n        private final String problem;\n        public InvalidExpenseException(String problem) {\n            super(problem);\n            this.problem = problem;\n        }\n        public String problem() { return problem; }\n    }\n\n    // W: validates only the FIRST rule and its message is a constant \u2014\n    // blank categories pass through and every failure reports \"bad\".\n    public record Expense(String id, String category, int cents) {\n        public Expense {\n            if (id == null || id.isBlank()) throw new InvalidExpenseException(\"bad\");\n        }\n    }\n}\n";
R["javi-p15-expense-repo"] = "\nimport java.util.*;\n\npublic class Solution {\n    public record Expense(String id, String category, int cents) {}\n\n    public interface ExpenseStore {\n        void save(Expense e);\n        Optional<Expense> find(String id);\n        List<Expense> all();\n    }\n\n    public static class DuplicateExpenseException extends RuntimeException {\n        public DuplicateExpenseException(String m) { super(m); }\n    }\n\n    public static class InMemoryExpenseStore implements ExpenseStore {\n        private final Map<String, Expense> store = new LinkedHashMap<>();\n\n        @Override public void save(Expense e) {\n            Expense old = store.get(e.id());\n            if (old != null && !old.category().equals(e.category())) {\n                throw new DuplicateExpenseException(\"category conflict for \" + e.id());\n            }\n            store.put(e.id(), e);\n        }\n\n        @Override public Optional<Expense> find(String id) { return Optional.ofNullable(store.get(id)); }\n        @Override public List<Expense> all() { return new ArrayList<>(store.values()); }\n    }\n}\n";
W["javi-p15-expense-repo"] = "\nimport java.util.*;\n\npublic class Solution {\n    public record Expense(String id, String category, int cents) {}\n\n    public interface ExpenseStore {\n        void save(Expense e);\n        Optional<Expense> find(String id);\n        List<Expense> all();\n    }\n\n    public static class DuplicateExpenseException extends RuntimeException {\n        public DuplicateExpenseException(String m) { super(m); }\n    }\n\n    public static class InMemoryExpenseStore implements ExpenseStore {\n        private final Map<String, Expense> store = new LinkedHashMap<>();\n\n        // W: ANY re-save throws \u2014 legitimate cent updates are rejected,\n        // so upsert semantics are gone.\n        @Override public void save(Expense e) {\n            if (store.containsKey(e.id())) {\n                throw new DuplicateExpenseException(\"duplicate \" + e.id());\n            }\n            store.put(e.id(), e);\n        }\n\n        @Override public Optional<Expense> find(String id) { return Optional.ofNullable(store.get(id)); }\n        @Override public List<Expense> all() { return new ArrayList<>(store.values()); }\n    }\n}\n";
R["javi-p15-expense-report"] = "\nimport java.util.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public record Expense(String id, String category, int cents) {}\n\n    public static class InMemoryExpenseStore {\n        private final Map<String, Expense> store = new LinkedHashMap<>();\n        public void save(Expense e) { store.put(e.id(), e); }\n        public Optional<Expense> find(String id) { return Optional.ofNullable(store.get(id)); }\n        public List<Expense> all() { return new ArrayList<>(store.values()); }\n    }\n\n    public static int totalForCategory(InMemoryExpenseStore store, String category) {\n        return store.all().stream()\n            .filter(e -> e.category().equals(category))\n            .mapToInt(Expense::cents)\n            .sum();\n    }\n\n    public static List<String> categoryTotals(InMemoryExpenseStore store) {\n        return store.all().stream()\n            .collect(Collectors.groupingBy(Expense::category,\n                Collectors.summingInt(Expense::cents)))\n            .entrySet().stream()\n            .sorted(Map.Entry.comparingByKey())\n            .map(e -> e.getKey() + \":\" + e.getValue())\n            .collect(Collectors.toList());\n    }\n\n    public static Optional<String> biggestSpend(InMemoryExpenseStore store) {\n        return store.all().stream()\n            .max(Comparator.comparingInt(Expense::cents)\n                .thenComparing(Expense::id, Comparator.reverseOrder()))\n            .map(Expense::id);\n    }\n}\n";
W["javi-p15-expense-report"] = "\nimport java.util.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public record Expense(String id, String category, int cents) {}\n\n    public static class InMemoryExpenseStore {\n        private final Map<String, Expense> store = new LinkedHashMap<>();\n        public void save(Expense e) { store.put(e.id(), e); }\n        public Optional<Expense> find(String id) { return Optional.ofNullable(store.get(id)); }\n        public List<Expense> all() { return new ArrayList<>(store.values()); }\n    }\n\n    public static int totalForCategory(InMemoryExpenseStore store, String category) {\n        return store.all().stream()\n            .filter(e -> e.category().equals(category))\n            .mapToInt(Expense::cents)\n            .sum();\n    }\n\n    public static List<String> categoryTotals(InMemoryExpenseStore store) {\n        return store.all().stream()\n            .collect(Collectors.groupingBy(Expense::category,\n                Collectors.summingInt(Expense::cents)))\n            .entrySet().stream()\n            .sorted(Map.Entry.comparingByKey())\n            .map(e -> e.getKey() + \":\" + e.getValue())\n            .collect(Collectors.toList());\n    }\n\n    // W: tie-break is REVERSED \u2014 equal cents pick the LARGEST id, so\n    // \"b\" beats \"a\" on ties. The deterministic tie-break contract breaks.\n    public static Optional<String> biggestSpend(InMemoryExpenseStore store) {\n        return store.all().stream()\n            .max(Comparator.comparingInt(Expense::cents)\n                .thenComparing(Expense::id))\n            .map(Expense::id);\n    }\n}\n";
R["javi-checkpoint-m15-capstone"] = "\nimport java.util.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public record Expense(String id, String category, int cents) {\n        public Expense {\n            if (id == null || id.isBlank()) throw new IllegalArgumentException(\"blank id\");\n            if (category == null || category.isBlank()) throw new IllegalArgumentException(\"blank category\");\n            if (cents <= 0) throw new IllegalArgumentException(\"non-positive cents\");\n        }\n    }\n\n    public interface ExpenseStore {\n        void save(Expense e);\n        Optional<Expense> find(String id);\n        List<Expense> all();\n    }\n\n    public static class InMemoryExpenseStore implements ExpenseStore {\n        private final Map<String, Expense> store = new LinkedHashMap<>();\n        @Override public void save(Expense e) { store.put(e.id(), e); }\n        @Override public Optional<Expense> find(String id) { return Optional.ofNullable(store.get(id)); }\n        @Override public List<Expense> all() { return new ArrayList<>(store.values()); }\n    }\n\n    public static class ExpenseService {\n        private final ExpenseStore store;\n        public ExpenseService(ExpenseStore store) { this.store = store; }\n\n        public void add(String id, String category, int cents) {\n            store.save(new Expense(id, category, cents));\n        }\n\n        public Map<String, Integer> totalsByCategory() {\n            return store.all().stream()\n                .collect(Collectors.groupingBy(Expense::category,\n                    Collectors.summingInt(Expense::cents)));\n        }\n\n        public Optional<String> topExpense() {\n            return store.all().stream()\n                .max(Comparator.comparingInt(Expense::cents)\n                    .thenComparing(Expense::id, Comparator.reverseOrder()))\n                .map(Expense::id);\n        }\n    }\n}\n";
W["javi-checkpoint-m15-capstone"] = "\nimport java.util.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public record Expense(String id, String category, int cents) {\n        public Expense {\n            if (id == null || id.isBlank()) throw new IllegalArgumentException(\"blank id\");\n            if (category == null || category.isBlank()) throw new IllegalArgumentException(\"blank category\");\n            if (cents <= 0) throw new IllegalArgumentException(\"non-positive cents\");\n        }\n    }\n\n    public interface ExpenseStore {\n        void save(Expense e);\n        Optional<Expense> find(String id);\n        List<Expense> all();\n    }\n\n    public static class InMemoryExpenseStore implements ExpenseStore {\n        private final Map<String, Expense> store = new LinkedHashMap<>();\n        @Override public void save(Expense e) { store.put(e.id(), e); }\n        @Override public Optional<Expense> find(String id) { return Optional.ofNullable(store.get(id)); }\n        @Override public List<Expense> all() { return new ArrayList<>(store.values()); }\n    }\n\n    public static class ExpenseService {\n        private final ExpenseStore store;\n        public ExpenseService(ExpenseStore store) { this.store = store; }\n\n        public void add(String id, String category, int cents) {\n            store.save(new Expense(id, category, cents));\n        }\n\n        // W: totals count DISTINCT categories but ignore amounts \u2014\n        // every sum comes back as the number of expenses, not their total.\n        public Map<String, Integer> totalsByCategory() {\n            Map<String, Integer> out = new HashMap<>();\n            for (Expense e : store.all()) out.put(e.category(), out.getOrDefault(e.category(), 0) + 1);\n            return out;\n        }\n\n        public Optional<String> topExpense() {\n            return store.all().stream()\n                .max(Comparator.comparingInt(Expense::cents)\n                    .thenComparing(Expense::id, Comparator.reverseOrder()))\n                .map(Expense::id);\n        }\n    }\n}\n";
